// 科目题库：英语（由 exam-bank.js 拆分而来，内容未改动）
window.SUBJECT_BANK = window.SUBJECT_BANK || {};
window.SUBJECT_BANK['english'] = {"id":"english","name":"英语","chapters":[{"id":"english-c1","name":"词汇"},{"id":"english-c2","name":"情景"},{"id":"english-c3","name":"语法"},{"id":"english-c4","name":"阅读"}],"questions":[{"id":"english-vocab-1","origNo":1,"type":"single","stem":"The new policy will ______ the living standards of the people in rural areas.","options":[{"key":"A","text":"affect"},{"key":"B","text":"effect"},{"key":"C","text":"afford"},{"key":"D","text":"effort"}],"answer":"A","explanation":"句意为新政策将影响人民生活水平，affect意为影响（动词），effect作动词意为促成，故选A。","chapter":"词汇"},{"id":"english-vocab-2","origNo":2,"type":"single","stem":"She has made up her mind to ______ the task even if it means working overtime.","options":[{"key":"A","text":"accomplish"},{"key":"B","text":"accompany"},{"key":"C","text":"accumulate"},{"key":"D","text":"accommodate"}],"answer":"A","explanation":"make up one's mind to do sth决心做某事，accomplish完成（任务），符合语境，故选A。","chapter":"词汇"},{"id":"english-vocab-3","origNo":3,"type":"single","stem":"The manager was ______ of stealing company funds and was later dismissed.","options":[{"key":"A","text":"accused"},{"key":"B","text":"charged"},{"key":"C","text":"blamed"},{"key":"D","text":"scolded"}],"answer":"A","explanation":"be accused of被指控（偷窃），固定搭配，charged搭配with，故选A。","chapter":"词汇"},{"id":"english-vocab-4","origNo":4,"type":"single","stem":"The old building was completely ______ by fire last night, leaving nothing but ashes.","options":[{"key":"A","text":"damaged"},{"key":"B","text":"ruined"},{"key":"C","text":"destroyed"},{"key":"D","text":"hurt"}],"answer":"C","explanation":"be destroyed by fire被火完全摧毁，destroy指彻底破坏，damage程度较轻，故选C。","chapter":"词汇"},{"id":"english-vocab-5","origNo":5,"type":"single","stem":"You should ______ the opportunity to learn from experienced colleagues while you are still a new employee.","options":[{"key":"A","text":"take"},{"key":"B","text":"make"},{"key":"C","text":"get"},{"key":"D","text":"seize"}],"answer":"D","explanation":"seize the opportunity抓住机会，固定搭配，故选D。","chapter":"词汇"},{"id":"english-vocab-6","origNo":6,"type":"single","stem":"The conference has been ______ until next Friday due to the unexpected absence of the keynote speaker.","options":[{"key":"A","text":"put off"},{"key":"B","text":"put away"},{"key":"C","text":"put out"},{"key":"D","text":"put up"}],"answer":"A","explanation":"put off推迟，符合因故延期会议的语境；put away收好，put out扑灭，故选A。","chapter":"词汇"},{"id":"english-vocab-7","origNo":7,"type":"single","stem":"He is a very ______ person and never gets angry even when others are rude to him.","options":[{"key":"A","text":"patient"},{"key":"B","text":"confident"},{"key":"C","text":"tolerant"},{"key":"D","text":"modest"}],"answer":"C","explanation":"tolerant宽容的、能容忍的，符合从不生气，patient侧重耐心，故选C。","chapter":"词汇"},{"id":"english-vocab-8","origNo":8,"type":"single","stem":"The company is ______ new ways to reduce production costs without sacrificing product quality.","options":[{"key":"A","text":"looking after"},{"key":"B","text":"looking into"},{"key":"C","text":"looking for"},{"key":"D","text":"looking up"}],"answer":"C","explanation":"look for寻找（新方法），符合公司寻找降低成本途径的语境，故选C。","chapter":"词汇"},{"id":"english-vocab-9","origNo":9,"type":"single","stem":"It is ______ that all students should arrive at the examination hall at least 15 minutes before the test starts.","options":[{"key":"A","text":"requested"},{"key":"B","text":"demanded"},{"key":"C","text":"required"},{"key":"D","text":"acquired"}],"answer":"C","explanation":"It is required that要求……（规定），表硬性要求，故选C。","chapter":"词汇"},{"id":"english-vocab-10","origNo":10,"type":"single","stem":"She ______ her success to hard work and perseverance rather than to luck.","options":[{"key":"A","text":"contributes"},{"key":"B","text":"distributes"},{"key":"C","text":"attributes"},{"key":"D","text":"dedicates"}],"answer":"C","explanation":"attribute...to...把……归因于……，符合把成功归于努力，故选C。","chapter":"词汇"},{"id":"english-vocab-11","origNo":11,"type":"single","stem":"I can’t ______ the difference between these two words, as they seem to have exactly the same meaning.","options":[{"key":"A","text":"tell"},{"key":"B","text":"say"},{"key":"C","text":"speak"},{"key":"D","text":"talk"}],"answer":"A","explanation":"tell the difference辨别差异，固定搭配，故选A。","chapter":"词汇"},{"id":"english-vocab-12","origNo":12,"type":"single","stem":"The newly published book ______ a wide range of topics, from history to modern technology.","options":[{"key":"A","text":"covers"},{"key":"B","text":"contains"},{"key":"C","text":"includes"},{"key":"D","text":"concludes"}],"answer":"A","explanation":"cover涵盖（话题范围），书籍覆盖广泛主题，故选A。","chapter":"词汇"},{"id":"english-vocab-13","origNo":13,"type":"single","stem":"The doctor ______ him to give up smoking for the sake of his health, but he just wouldn’t listen.","options":[{"key":"A","text":"persuaded"},{"key":"B","text":"advised"},{"key":"C","text":"suggested"},{"key":"D","text":"convinced"}],"answer":"B","explanation":"advise sb to do sth建议某人做某事，固定搭配，persuade强调说服成功，故选B。","chapter":"词汇"},{"id":"english-vocab-14","origNo":14,"type":"single","stem":"The witness’s account of the accident didn’t ______ with what the other witnesses had reported.","options":[{"key":"A","text":"agree"},{"key":"B","text":"correspond"},{"key":"C","text":"match"},{"key":"D","text":"compare"}],"answer":"B","explanation":"correspond with与……一致，符合证词与事实相符，故选B。","chapter":"词汇"},{"id":"english-vocab-15","origNo":15,"type":"single","stem":"The little boy showed great ______ in solving the difficult math problem all by himself.","options":[{"key":"A","text":"intelligence"},{"key":"B","text":"wisdom"},{"key":"C","text":"talent"},{"key":"D","text":"ability"}],"answer":"A","explanation":"intelligence智力，show great intelligence表现出很高智力，故选A。","chapter":"词汇"},{"id":"english-vocab-16","origNo":16,"type":"single","stem":"The two countries have finally reached an ______ to cooperate in the field of environmental protection.","options":[{"key":"A","text":"agreement"},{"key":"B","text":"arrangement"},{"key":"C","text":"appointment"},{"key":"D","text":"approval"}],"answer":"A","explanation":"reach an agreement达成协议，固定搭配，故选A。","chapter":"词汇"},{"id":"english-vocab-17","origNo":17,"type":"single","stem":"He is ______ to lose his temper when things don’t go his way, so you’d better be careful.","options":[{"key":"A","text":"likely"},{"key":"B","text":"probable"},{"key":"C","text":"possible"},{"key":"D","text":"liable"}],"answer":"D","explanation":"be liable to易于……的（脾气），表倾向，故选D。","chapter":"词汇"},{"id":"english-vocab-18","origNo":18,"type":"single","stem":"The old professor has ______ a large number of outstanding students who have made great contributions to society.","options":[{"key":"A","text":"trained"},{"key":"B","text":"educated"},{"key":"C","text":"cultivated"},{"key":"D","text":"brought"}],"answer":"C","explanation":"cultivate培养（人才），教授培养大批优秀学生，故选C。","chapter":"词汇"},{"id":"english-vocab-19","origNo":19,"type":"single","stem":"The film was so ______ that many people in the audience were moved to tears.","options":[{"key":"A","text":"touched"},{"key":"B","text":"touching"},{"key":"C","text":"moved"},{"key":"D","text":"moving"}],"answer":"B","explanation":"touching令人感动的（修饰物film），moved被人感动，故选B。","chapter":"词汇"},{"id":"english-vocab-20","origNo":20,"type":"single","stem":"It is reported that the government will ______ a new set of measures to deal with air pollution.","options":[{"key":"A","text":"adopt"},{"key":"B","text":"adapt"},{"key":"C","text":"adjust"},{"key":"D","text":"admit"}],"answer":"A","explanation":"adopt采纳（新政策），adapt适应、改编，形近词辨析，故选A。","chapter":"词汇"},{"id":"english-scene-1","origNo":1,"type":"single","stem":"— Hey, my favorite band’s playing at the campus festival next Friday! — Wait, _________ — confirm our group work division now?","options":[{"key":"A","text":"Please turn over a new leaf"},{"key":"B","text":"Don’t pull our weight"},{"key":"C","text":"Let’s stick to the point"},{"key":"D","text":"You ticked all the right box"}],"answer":"C","explanation":"对方分享乐队演出的好消息，应表示赞同参与，选C，故选C。","chapter":"情景"},{"id":"english-scene-2","origNo":2,"type":"single","stem":"— Good news! I’ve found a summer job! — _________. Anything interesting?","options":[{"key":"A","text":"It’s a good idea"},{"key":"B","text":"You can’t be serious"},{"key":"C","text":"That’s great"},{"key":"D","text":"Check it out for yourself"}],"answer":"C","explanation":"对方告知找到暑假工作，应表示祝贺，That's great太棒了，故选C。","chapter":"情景"},{"id":"english-scene-3","origNo":3,"type":"single","stem":"— How did you find the film *Zootopia 2*? — _________. I can’t think too highly of it.","options":[{"key":"A","text":"It makes no sense"},{"key":"B","text":"It’s up to you"},{"key":"C","text":"It’s awful"},{"key":"D","text":"It’s really amazing"}],"answer":"D","explanation":"询问对电影看法，肯定回答It's really amazing非常精彩，故选D。","chapter":"情景"},{"id":"english-scene-4","origNo":4,"type":"single","stem":"— Here is a new edition of *China Daily*. Do you want to have a look? — _________! Let me see it.","options":[{"key":"A","text":"Don’t bother"},{"key":"B","text":"Not really"},{"key":"C","text":"By all means"},{"key":"D","text":"Mind your own business"}],"answer":"C","explanation":"对方问是否要看报纸，应欣然接受By all means当然可以，故选C。","chapter":"情景"},{"id":"english-scene-5","origNo":5,"type":"single","stem":"—Skipping breakfast is a good way to lose weight. —______. Actually it has the opposite effect.","options":[{"key":"A","text":"I’m glad to know that"},{"key":"B","text":"I can’t agree more"},{"key":"C","text":"That’s not the case"},{"key":"D","text":"That’s for sure"}],"answer":"C","explanation":"对方观点有误（不吃早餐减肥），应反驳That's not the case并非如此，故选C。","chapter":"情景"},{"id":"english-scene-6","origNo":6,"type":"single","stem":"—You seem to be in a really good mood. —I finished my final examination today. ________! Now I’m free.","options":[{"key":"A","text":"What a coincidence"},{"key":"B","text":"What a relief"},{"key":"C","text":"I have got it"},{"key":"D","text":"I have had enough."}],"answer":"B","explanation":"心情好因事情顺利，What a relief松了一口气，符合语境，故选B。","chapter":"情景"},{"id":"english-scene-7","origNo":7,"type":"single","stem":"— I feel very thankful for your help when a serious accident happened to my brother yesterday. — ______. But luckily, he had a narrow escape.","options":[{"key":"A","text":"Don’t worry about it"},{"key":"B","text":"Don’t overemphasize it"},{"key":"C","text":"Don’t take it seriously"},{"key":"D","text":"Don’t mention it"}],"answer":"D","explanation":"对方表达感谢，应礼貌回应Don't mention it别客气，故选D。","chapter":"情景"},{"id":"english-scene-8","origNo":8,"type":"single","stem":"— I plan to sign up for the school’s debate competition, but I’m worried about my public speaking skills. — ________. You’ve been practicing debates in class for months and you’re ready for it.","options":[{"key":"A","text":"I’d rather you didn’t"},{"key":"B","text":"That’s a bad idea"},{"key":"C","text":"You’ve got this"},{"key":"D","text":"Never mind"}],"answer":"C","explanation":"对方犹豫参加辩论赛，应鼓励You've got this你能行，故选C。","chapter":"情景"},{"id":"english-scene-9","origNo":9,"type":"single","stem":"— Excuse me, could you tell me what you think about my proposal of organizing the campus book fair? I’ve prepared several plans but I’m not sure if they are practical… — ________. Just tell me the core idea of your plan and whether you have got the school’s approval or not.","options":[{"key":"A","text":"Don’t beat around the bush"},{"key":"B","text":"I’m all ears"},{"key":"C","text":"You can say that again"},{"key":"D","text":"It’s a piece of cake"}],"answer":"A","explanation":"对方询问对建议的看法，I'm all ears洗耳躬听，符合倾听语境，故选B。","chapter":"情景"},{"id":"english-scene-10","origNo":10,"type":"single","stem":"—I think this contemporary abstract painting just looks like a mess of colours. —______. Actually, I find it quite meaningful.","options":[{"key":"A","text":"I beg to differ"},{"key":"B","text":"You read my mind"},{"key":"C","text":"I couldn’t agree more"},{"key":"D","text":"You’ve got me there"}],"answer":"A","explanation":"对方贬低画作，自己不同意应表达I beg to differ恕我不能苟同，故选A。","chapter":"情景"},{"id":"english-scene-11","origNo":11,"type":"single","stem":"—It’s a real dilemma. I can't decide which major to choose. Physics and literature both appeal to me. —______. But you should choose the one that you are most passionate about.","options":[{"key":"A","text":"It’s a deal"},{"key":"B","text":"Never say never"},{"key":"C","text":"Don't mention it"},{"key":"D","text":"That's a tough call"}],"answer":"D","explanation":"对方面临两难选择，That's a tough call确实难抉择，符合语境，故选D。","chapter":"情景"},{"id":"english-scene-12","origNo":12,"type":"single","stem":"The research team will _________ during the expedition (探险), as they must continue collecting data despite the approaching storm.","options":[{"key":"A","text":"rain cats and dogs"},{"key":"B","text":"brave the elements"},{"key":"C","text":"burn the midnight oil"},{"key":"D","text":"beat around the bush"}],"answer":"B","explanation":"探险队要面对恶劣天气，brave the elements顶风冒雨，符合语境，故选B。","chapter":"情景"},{"id":"english-scene-13","origNo":13,"type":"single","stem":"—I stayed up all night cramming for the math test, and now I can’t remember a single formula! —Ugh, ________ when you try to memorize everything at the last minute. Next time, maybe study a little each day instead?","options":[{"key":"A","text":"that happens"},{"key":"B","text":"it turns"},{"key":"C","text":"this exists"},{"key":"D","text":"there arises"}],"answer":"A","explanation":"对方熬夜考试状态差，安慰that happens常有的事，故选A。","chapter":"情景"},{"id":"english-scene-14","origNo":14,"type":"single","stem":"— Say, what’s your favorite sport? — Hmmm... it’s hard to say. I like golf a lot — but I guess I like tennis better. — Do you play much tennis? — Yes, quite a bit. ______ — Sorry. I’m strictly a spectator — football, baseball, basketball, golf... I watch them all.","options":[{"key":"A","text":"Where do you often spend your weekend?"},{"key":"B","text":"Who is your favorite player?"},{"key":"C","text":"Why don’t you do exercise regularly?"},{"key":"D","text":"How about a game sometime?"}],"answer":"D","explanation":"谈论喜爱的运动后，自然提议How about a game sometime有空比一场，故选D。","chapter":"情景"},{"id":"english-scene-15","origNo":15,"type":"single","stem":"— Excuse me, is this seat taken? — No. it isn’t. — ______, so my friend and I can sit together? — No, not at all. — Thanks a lot.","options":[{"key":"A","text":"Would you leave me alone for a while"},{"key":"B","text":"Would you mind getting out of my sight"},{"key":"C","text":"Would you mind moving over one"},{"key":"D","text":"Would my friend take your seat"}],"answer":"C","explanation":"询问座位是否有人，请求挪动Would you mind moving over one，故选C。","chapter":"情景"},{"id":"english-scene-16","origNo":16,"type":"single","stem":"— What time is it? — It’s a quarter to five. — ______ — Five or five-thirty. He said it didn’t make any difference.","options":[{"key":"A","text":"Jim is waiting for us — let’s hurry up!"},{"key":"B","text":"Where are we expected to meet Jim later?"},{"key":"C","text":"Jim is said to be with us at five tomorrow afternoon."},{"key":"D","text":"Aren’t we supposed to be at Jim’s house by five o’ clock?"}],"answer":"D","explanation":"问时间后关心是否迟到，Aren't we supposed to be...by five我们该五点到吧，故选D。","chapter":"情景"},{"id":"english-scene-17","origNo":17,"type":"single","stem":"— Haven’t I seen you somewhere before? — No, I don’t think so. — But you do look familiar. Wait a second... I know... We were on the same flight to New York last month. — Oh, yes. Now I remember. What a coincidence to meet in San Francisco! — Well, you know what they say — ______.","options":[{"key":"A","text":"it’s a small world."},{"key":"B","text":"you are so forgetful."},{"key":"C","text":"it’s the flight where stories begin."},{"key":"D","text":"you cannot step into the same river twice."}],"answer":"A","explanation":"对方说似曾相识，回应it's a small world世界真小，故选A。","chapter":"情景"},{"id":"english-scene-18","origNo":18,"type":"single","stem":"— Excuse me. I wonder if you can help me. — Sure. What is it? — I want to have my hair cut, but I can’t find a barber shop. — I know where one is.______","options":[{"key":"A","text":"I’m not so sure."},{"key":"B","text":"Come on — I’ll show you."},{"key":"C","text":"It sells cool T-shirts."},{"key":"D","text":"You won’t take the wrong way."}],"answer":"B","explanation":"对方请求帮助，热情回应Come on—I'll show you来我给你指路，故选B。","chapter":"情景"},{"id":"english-scene-19","origNo":19,"type":"single","stem":"— Diana and I went for a drive in the country on Saturday. — ______. Where did you go?","options":[{"key":"A","text":"That sounds nice"},{"key":"B","text":"Not really"},{"key":"C","text":"Thank goodness"},{"key":"D","text":"Take it seriously"}],"answer":"A","explanation":"对方分享周六郊游，应回应That sounds nice听起来不错，故选A。","chapter":"情景"},{"id":"english-scene-20","origNo":20,"type":"single","stem":"-The team worked together and solved the technical problem in just two hours. -See? _____","options":[{"key":"A","text":"Every cloud has a silver lining."},{"key":"B","text":"Too many cooks spoil the broth."},{"key":"C","text":"Many hands make light work."},{"key":"D","text":"The early bird catches the worm."}],"answer":"C","explanation":"团队协作快速解决问题，Many hands make light work人多好办事，故选C。","chapter":"情景"},{"id":"english-gram-1","origNo":1,"type":"single","stem":"—Is your brother going camping? —He’s signed up but he’s considering________.","options":[{"key":"A","text":"not to go"},{"key":"B","text":"not going"},{"key":"C","text":"won’t go"},{"key":"D","text":"not go"}],"answer":"B","explanation":"consider后接动名词，否定式为not going，故选B。","chapter":"语法"},{"id":"english-gram-2","origNo":2,"type":"single","stem":"In nature some animals actively defend the area_________ they depend for the resources.","options":[{"key":"A","text":"in which"},{"key":"B","text":"on which"},{"key":"C","text":"which"},{"key":"D","text":"where"}],"answer":"B","explanation":"定语从句修饰area，depend on the area，介词+which结构用on which，故选B。","chapter":"语法"},{"id":"english-gram-3","origNo":3,"type":"single","stem":"—What a terrible accident! —Yes. It happened __________ he four roads meet.","options":[{"key":"A","text":"where"},{"key":"B","text":"that"},{"key":"C","text":"when"},{"key":"D","text":"as"}],"answer":"A","explanation":"强调句型It happened where...，where引导地点状语从句，故选A。","chapter":"语法"},{"id":"english-gram-4","origNo":4,"type":"single","stem":"Mr. White, who I ______ to the south of France, still lives in London.","options":[{"key":"A","text":"think to have moved"},{"key":"B","text":"think had moved"},{"key":"C","text":"thought have moved"},{"key":"D","text":"thought had moved"}],"answer":"D","explanation":"thought后接宾语从句，move发生在thought之前用过去完成时had moved，故选D。","chapter":"语法"},{"id":"english-gram-5","origNo":5,"type":"single","stem":"The officers narrowly escaped ___________ in the hot battle.","options":[{"key":"A","text":"have killed"},{"key":"B","text":"to kill"},{"key":"C","text":"to be killed"},{"key":"D","text":"being killed"}],"answer":"D","explanation":"escape后接动名词，且被杀死表被动，用being killed，故选D。","chapter":"语法"},{"id":"english-gram-6","origNo":6,"type":"single","stem":"The plan has to be ______ to meet the real situation.","options":[{"key":"A","text":"adjusted"},{"key":"B","text":"adapted"},{"key":"C","text":"produced"},{"key":"D","text":"refunded"}],"answer":"A","explanation":"be adjusted to适应/调整以符合实际情况，故选A。","chapter":"语法"},{"id":"english-gram-7","origNo":7,"type":"single","stem":"_______about her ideal university, Jenny said she had no idea.","options":[{"key":"A","text":"Ask"},{"key":"B","text":"When asking"},{"key":"C","text":"Asking"},{"key":"D","text":"When asked"}],"answer":"D","explanation":"Jenny与ask为被动关系，用过去分词，When asked被问到时，故选D。","chapter":"语法"},{"id":"english-gram-8","origNo":8,"type":"single","stem":"I showed him the pictures I _______ of the animals the day before.","options":[{"key":"A","text":"was taken"},{"key":"B","text":"have taken"},{"key":"C","text":"had taken"},{"key":"D","text":"was taking"}],"answer":"C","explanation":"拍照发生在showed之前，用过去完成时had taken，故选C。","chapter":"语法"},{"id":"english-gram-9","origNo":9,"type":"single","stem":"Look at the sign, Sir. We don’t permit ________ in the hall.","options":[{"key":"A","text":"smoke"},{"key":"B","text":"to smoke"},{"key":"C","text":"smoking"},{"key":"D","text":"to have a smoke"}],"answer":"C","explanation":"permit后接动名词permit doing sth允许做某事，故选C。","chapter":"语法"},{"id":"english-gram-10","origNo":10,"type":"single","stem":"Even the best writers sometimes find themselves________ for words.","options":[{"key":"A","text":"losing"},{"key":"B","text":"lost"},{"key":"C","text":"loses"},{"key":"D","text":"be lost"}],"answer":"B","explanation":"find oneself lost发现自己迷失，过去分词作宾补表状态，故选B。","chapter":"语法"},{"id":"english-gram-11","origNo":11,"type":"single","stem":"Most environmental problems exist because adequate measures for preventing them _______ taken in the past.","options":[{"key":"A","text":"had not been"},{"key":"B","text":"were not being"},{"key":"C","text":"were not"},{"key":"D","text":"was not"}],"answer":"C","explanation":"measures与take为被动，过去时被动were not taken，故选C。","chapter":"语法"},{"id":"english-gram-12","origNo":12,"type":"single","stem":"He ran as fast as he could _____ to catch the early bus.","options":[{"key":"A","text":"to hope"},{"key":"B","text":"hope"},{"key":"C","text":"hoping"},{"key":"D","text":"hoped"}],"answer":"C","explanation":"伴随状语用现在分词hoping，表伴随目的，故选C。","chapter":"语法"},{"id":"english-gram-13","origNo":13,"type":"single","stem":"You should be careful how you judge people ________ you cannot sum up a man's life in one moment.","options":[{"key":"A","text":"as though"},{"key":"B","text":"even though"},{"key":"C","text":"now that"},{"key":"D","text":"in that"}],"answer":"D","explanation":"in that因为、在于（引导原因状语从句），符合语境，故选D。","chapter":"语法"},{"id":"english-gram-14","origNo":14,"type":"single","stem":"—I haven't heard from John for a long time. —What do you suppose ________ to him?","options":[{"key":"A","text":"was happening"},{"key":"B","text":"to happen"},{"key":"C","text":"has happened"},{"key":"D","text":"had happened"}],"answer":"C","explanation":"现在完成时has happened表对现在的影响，故选C。","chapter":"语法"},{"id":"english-gram-15","origNo":15,"type":"single","stem":"____ at home, we can enjoy music or watch live sports games.","options":[{"key":"A","text":"To sit"},{"key":"B","text":"Sitting"},{"key":"C","text":"Sitted"},{"key":"D","text":"Being sitted"}],"answer":"B","explanation":"Sitting at home坐在家里，现在分词作状语，故选B。","chapter":"语法"},{"id":"english-gram-16","origNo":16,"type":"single","stem":"You will find the laptop well-designed when he ______ it ______.","options":[{"key":"A","text":"will bring …back"},{"key":"B","text":"brings …back"},{"key":"C","text":"takes …away"},{"key":"D","text":"will take …away"}],"answer":"B","explanation":"时间状语从句主将从现，when引导从句用一般现在时brings back，故选B。","chapter":"语法"},{"id":"english-gram-17","origNo":17,"type":"single","stem":"If you apply yourself to ______ about the problem, you will soon solve it.","options":[{"key":"A","text":"think"},{"key":"B","text":"be thought"},{"key":"C","text":"thinking"},{"key":"D","text":"have thought"}],"answer":"C","explanation":"apply oneself to后接动名词thinking，to为介词，故选C。","chapter":"语法"},{"id":"english-gram-18","origNo":18,"type":"single","stem":"There_______a sports meeting last week.","options":[{"key":"A","text":"be"},{"key":"B","text":"is"},{"key":"C","text":"was"},{"key":"D","text":"had"}],"answer":"C","explanation":"There be句型过去时，last week用There was，故选C。","chapter":"语法"},{"id":"english-gram-19","origNo":19,"type":"single","stem":"The ceremony of Syria’s admission into the Belt and Road Initiative (BRI)________ in the capital Damascus on Jan. 12 and was attended by Fadi Khalil, head of the commission, who noted that Syria________ one of the main countries on the ancient Silk Road, particularly the cities of Aleppo and Palmyra.","options":[{"key":"A","text":"took place; had been"},{"key":"B","text":"was taken place; has been"},{"key":"C","text":"was taken place; was"},{"key":"D","text":"took place; was"}],"answer":"D","explanation":"take place无被动用took place；was attended表被参加，故选D。","chapter":"语法"},{"id":"english-gram-20","origNo":20,"type":"single","stem":"What is it _____ his daughter needs most?","options":[{"key":"A","text":"what"},{"key":"B","text":"which"},{"key":"C","text":"that"},{"key":"D","text":"if"}],"answer":"C","explanation":"强调句型What is it that...，强调句用that，故选C。","chapter":"语法"},{"id":"english-read-1","origNo":1,"type":"single","stem":"【阅读材料】\n“Kevin! Kevin! Did you hear what I said?” Ms. Reed, the band director,\nlooked straight at him — she wanted him to take Robin’s place, since\nRobin had broken her arm, and play a solo at the concert. Kevin agreed,\ntrying hard to hide his sadness: he was terrified of performing on\nstage, *freezing up* completely when playing alone, even though he was\nthe best saxophone player in his middle school band and played with the\nsenior high band too.\nJames, his bandmate, felt sorry for him and shared how he’d fainted on\nstage during a solo because he was so nervous. The story only made Kevin\nmore worried, but something worse was coming. Kelly, the overly\ncompetitive top flutist in the state, stopped him, saying that the Youth\nSymphony director would come to the concert to listen to his solo — and\nif he played well, he could get a chance to try out. Her words made him\nfeel heavy inside; he’d wanted to join the Youth Symphony for a long\ntime but never had the courage to audition.\nRunning out of the school, Kevin thought of excuses to skip the solo:\npretending to be ill, saying he’d hurt his finger. But he knew his\nparents would see he was lying, and hurting his finger on purpose was\ntoo dangerous. By the time he got home, his mom was very happy, talking\nexcitedly about the Youth Symphony chance and Ms. Reed’s praise. Kevin\nlied that his day was okay, then went down to the furnace room — called\n“Kevin’s Dungeon” — his practice space. He picked up his saxophone, took\na deep breath, and started to play.\nThis time, he didn’t focus on the fear of messing up; he focused on the\nmusic he loved. Maybe this solo wasn’t a nightmare — it was a chance to\nturn his dream into reality.\nThe final note faded, and loud applause burst out. Kevin smiled and felt\na warm rush of joy in his heart. He finally understood that courage\nisn’t the lack of fear, but going ahead in spite of it. Dreams never\ncome to those who run away from challenges; they always wait for those\nwho dare to face their fears and try.\n\n【题目】\nWhy did Ms. Reed ask Kevin to play the solo at the concert?","options":[{"key":"A","text":"Kevin was the most skilled sax player in the senior high band."},{"key":"B","text":"Robin was unable to perform due to a broken arm."},{"key":"C","text":"The Youth Symphony director personally recommended Kevin."},{"key":"D","text":"Kevin had been eager to get the solo opportunity for a long time."}],"answer":"B","explanation":"Robin因手臂受伤无法演出，Ms Reed才请Kevin顶替独奏，故选B。","chapter":"阅读"},{"id":"english-read-2","origNo":2,"type":"single","stem":"【阅读材料】\n“Kevin! Kevin! Did you hear what I said?” Ms. Reed, the band director,\nlooked straight at him — she wanted him to take Robin’s place, since\nRobin had broken her arm, and play a solo at the concert. Kevin agreed,\ntrying hard to hide his sadness: he was terrified of performing on\nstage, *freezing up* completely when playing alone, even though he was\nthe best saxophone player in his middle school band and played with the\nsenior high band too.\nJames, his bandmate, felt sorry for him and shared how he’d fainted on\nstage during a solo because he was so nervous. The story only made Kevin\nmore worried, but something worse was coming. Kelly, the overly\ncompetitive top flutist in the state, stopped him, saying that the Youth\nSymphony director would come to the concert to listen to his solo — and\nif he played well, he could get a chance to try out. Her words made him\nfeel heavy inside; he’d wanted to join the Youth Symphony for a long\ntime but never had the courage to audition.\nRunning out of the school, Kevin thought of excuses to skip the solo:\npretending to be ill, saying he’d hurt his finger. But he knew his\nparents would see he was lying, and hurting his finger on purpose was\ntoo dangerous. By the time he got home, his mom was very happy, talking\nexcitedly about the Youth Symphony chance and Ms. Reed’s praise. Kevin\nlied that his day was okay, then went down to the furnace room — called\n“Kevin’s Dungeon” — his practice space. He picked up his saxophone, took\na deep breath, and started to play.\nThis time, he didn’t focus on the fear of messing up; he focused on the\nmusic he loved. Maybe this solo wasn’t a nightmare — it was a chance to\nturn his dream into reality.\nThe final note faded, and loud applause burst out. Kevin smiled and felt\na warm rush of joy in his heart. He finally understood that courage\nisn’t the lack of fear, but going ahead in spite of it. Dreams never\ncome to those who run away from challenges; they always wait for those\nwho dare to face their fears and try.\n\n【题目】\nThe underlined phrase “freezing up” in Paragraph 1 probably means _________.","options":[{"key":"A","text":"staying calm to deal with the performance"},{"key":"B","text":"feeling extremely cold on the frightening stage"},{"key":"C","text":"having great confidence in playing the solo"},{"key":"D","text":"being unable to move or act because of nervousness"}],"answer":"D","explanation":"freezing up指因紧张而僵住、无法行动，故选D。","chapter":"阅读"},{"id":"english-read-3","origNo":3,"type":"single","stem":"【阅读材料】\n“Kevin! Kevin! Did you hear what I said?” Ms. Reed, the band director,\nlooked straight at him — she wanted him to take Robin’s place, since\nRobin had broken her arm, and play a solo at the concert. Kevin agreed,\ntrying hard to hide his sadness: he was terrified of performing on\nstage, *freezing up* completely when playing alone, even though he was\nthe best saxophone player in his middle school band and played with the\nsenior high band too.\nJames, his bandmate, felt sorry for him and shared how he’d fainted on\nstage during a solo because he was so nervous. The story only made Kevin\nmore worried, but something worse was coming. Kelly, the overly\ncompetitive top flutist in the state, stopped him, saying that the Youth\nSymphony director would come to the concert to listen to his solo — and\nif he played well, he could get a chance to try out. Her words made him\nfeel heavy inside; he’d wanted to join the Youth Symphony for a long\ntime but never had the courage to audition.\nRunning out of the school, Kevin thought of excuses to skip the solo:\npretending to be ill, saying he’d hurt his finger. But he knew his\nparents would see he was lying, and hurting his finger on purpose was\ntoo dangerous. By the time he got home, his mom was very happy, talking\nexcitedly about the Youth Symphony chance and Ms. Reed’s praise. Kevin\nlied that his day was okay, then went down to the furnace room — called\n“Kevin’s Dungeon” — his practice space. He picked up his saxophone, took\na deep breath, and started to play.\nThis time, he didn’t focus on the fear of messing up; he focused on the\nmusic he loved. Maybe this solo wasn’t a nightmare — it was a chance to\nturn his dream into reality.\nThe final note faded, and loud applause burst out. Kevin smiled and felt\na warm rush of joy in his heart. He finally understood that courage\nisn’t the lack of fear, but going ahead in spite of it. Dreams never\ncome to those who run away from challenges; they always wait for those\nwho dare to face their fears and try.\n\n【题目】\nWhat made Kevin’s anxiety grow after he received the solo task?","options":[{"key":"A","text":"James told him about his own embarrassing solo experience."},{"key":"B","text":"His mother didn’t believe he could perform well on stage."},{"key":"C","text":"Kelly laughed at him for lacking the courage to audition."},{"key":"D","text":"He found his practice room was too small to play the saxophone."}],"answer":"A","explanation":"James讲述自己尴尬的独奏经历，加重了Kevin的焦虑，故选A。","chapter":"阅读"},{"id":"english-read-4","origNo":4,"type":"single","stem":"【阅读材料】\n“Kevin! Kevin! Did you hear what I said?” Ms. Reed, the band director,\nlooked straight at him — she wanted him to take Robin’s place, since\nRobin had broken her arm, and play a solo at the concert. Kevin agreed,\ntrying hard to hide his sadness: he was terrified of performing on\nstage, *freezing up* completely when playing alone, even though he was\nthe best saxophone player in his middle school band and played with the\nsenior high band too.\nJames, his bandmate, felt sorry for him and shared how he’d fainted on\nstage during a solo because he was so nervous. The story only made Kevin\nmore worried, but something worse was coming. Kelly, the overly\ncompetitive top flutist in the state, stopped him, saying that the Youth\nSymphony director would come to the concert to listen to his solo — and\nif he played well, he could get a chance to try out. Her words made him\nfeel heavy inside; he’d wanted to join the Youth Symphony for a long\ntime but never had the courage to audition.\nRunning out of the school, Kevin thought of excuses to skip the solo:\npretending to be ill, saying he’d hurt his finger. But he knew his\nparents would see he was lying, and hurting his finger on purpose was\ntoo dangerous. By the time he got home, his mom was very happy, talking\nexcitedly about the Youth Symphony chance and Ms. Reed’s praise. Kevin\nlied that his day was okay, then went down to the furnace room — called\n“Kevin’s Dungeon” — his practice space. He picked up his saxophone, took\na deep breath, and started to play.\nThis time, he didn’t focus on the fear of messing up; he focused on the\nmusic he loved. Maybe this solo wasn’t a nightmare — it was a chance to\nturn his dream into reality.\nThe final note faded, and loud applause burst out. Kevin smiled and felt\na warm rush of joy in his heart. He finally understood that courage\nisn’t the lack of fear, but going ahead in spite of it. Dreams never\ncome to those who run away from challenges; they always wait for those\nwho dare to face their fears and try.\n\n【题目】\nWe can infer from the last paragraph that Kevin finally chose to _________.","options":[{"key":"A","text":"pretend to be sick and miss the concert instantly"},{"key":"B","text":"gave up his dream of joining the Youth Symphony"},{"key":"C","text":"face the challenge and practice for the solo actively"},{"key":"D","text":"ask the band director to replace him with another student"}],"answer":"C","explanation":"Kevin最终选择面对挑战、积极练习独奏，故选C。","chapter":"阅读"},{"id":"english-read-5","origNo":5,"type":"single","stem":"【阅读材料】\n“Kevin! Kevin! Did you hear what I said?” Ms. Reed, the band director,\nlooked straight at him — she wanted him to take Robin’s place, since\nRobin had broken her arm, and play a solo at the concert. Kevin agreed,\ntrying hard to hide his sadness: he was terrified of performing on\nstage, *freezing up* completely when playing alone, even though he was\nthe best saxophone player in his middle school band and played with the\nsenior high band too.\nJames, his bandmate, felt sorry for him and shared how he’d fainted on\nstage during a solo because he was so nervous. The story only made Kevin\nmore worried, but something worse was coming. Kelly, the overly\ncompetitive top flutist in the state, stopped him, saying that the Youth\nSymphony director would come to the concert to listen to his solo — and\nif he played well, he could get a chance to try out. Her words made him\nfeel heavy inside; he’d wanted to join the Youth Symphony for a long\ntime but never had the courage to audition.\nRunning out of the school, Kevin thought of excuses to skip the solo:\npretending to be ill, saying he’d hurt his finger. But he knew his\nparents would see he was lying, and hurting his finger on purpose was\ntoo dangerous. By the time he got home, his mom was very happy, talking\nexcitedly about the Youth Symphony chance and Ms. Reed’s praise. Kevin\nlied that his day was okay, then went down to the furnace room — called\n“Kevin’s Dungeon” — his practice space. He picked up his saxophone, took\na deep breath, and started to play.\nThis time, he didn’t focus on the fear of messing up; he focused on the\nmusic he loved. Maybe this solo wasn’t a nightmare — it was a chance to\nturn his dream into reality.\nThe final note faded, and loud applause burst out. Kevin smiled and felt\na warm rush of joy in his heart. He finally understood that courage\nisn’t the lack of fear, but going ahead in spite of it. Dreams never\ncome to those who run away from challenges; they always wait for those\nwho dare to face their fears and try.\n\n【题目】\nWhat is the best title for the passage?","options":[{"key":"A","text":"A Successful Solo Performance"},{"key":"B","text":"The Competitive Flutist Kelly"},{"key":"C","text":"A Strict, Generous and Kind Band Director"},{"key":"D","text":"Stage Fright and A New Chance"}],"answer":"D","explanation":"文章围绕舞台恐惧与新的机会展开，Stage Fright and A New Chance最贴切，故选D。","chapter":"阅读"},{"id":"english-read-6","origNo":6,"type":"single","stem":"【阅读材料】\nThe 2026 CCTV Spring Festival Gala featured a breathtaking performance\nthat seamlessly blended traditional Chinese martial arts with\ncutting-edge technology: a carefully designed martial arts routine\nperformed by humanoid robots. This was not merely entertainment for the\naudience; it was a powerful declaration of China’s rapid and impressive\nadvancements in the fields of robotics and artificial intelligence.\nCompared to their debut just a year earlier, the 2026 robots\ndemonstrated astonishing progress in every aspect. Gone were the stiff,\nawkward and hesitant movements of the past. Dozens of Unitree’s G1\nhumanoid robots perfectly carried out complex and skillful actions,\nincluding high-speed flips, synchronized (同步的) nunchaku swings, and\neven the delicate, unsteady steps of “Drunken Fist.” They maintained\nstable balance, performed flawless formations, and interacted safely\nwith young human martial artists, a breakthrough that reflected huge\nleaps in both stability and dynamic motion control.\nBehind the striking performance lies a *convergence* of advanced\ntechnologies that together make such precise movements possible. Powered\nby highly developed AI control systems and equipped with LiDAR\n(激光雷达) sensors, the robots can map the 3D stage environment in real\ntime, enabling them to recognize their positions accurately and adjust\ntheir movements instantly to stay perfectly synchronized. Their flexible\njumps and flips rely on powerful actuators (执行器) and massive\nprofessional training data, proving that machines can now attain a level\nof athleticism once considered unique to humans.\nThe meaning of the display goes far beyond artistic effect. As a\nmilestone in intelligent manufacturing, the show underlines China’s\ngrowing competitiveness in the global humanoid robot industry. While\nChinese companies take a major share of the world market, the gala\nperformance more importantly shows the nation’s strong ability to\ncombine AI technology with a complete supply chain. It suggests a future\nwhere robots, having mastered the precision of kung fu, will undertake\ncomplex tasks in industry and daily life, turning technological strength\ninto practical social value.\n\n【题目】\nWhat was the most significant improvement in the 2026 robot performance compared to the previous year?","options":[{"key":"A","text":"The robots performed hesitant movements on a larger stage."},{"key":"B","text":"The robots moved more smoothly and performed complex actions."},{"key":"C","text":"The robots were controlled by young human performers."},{"key":"D","text":"The robots could speak and interact with the martial audience."}],"answer":"B","explanation":"2026年机器人动作更流畅、能完成复杂动作，是最大改进，故选B。","chapter":"阅读"},{"id":"english-read-7","origNo":7,"type":"single","stem":"【阅读材料】\nThe 2026 CCTV Spring Festival Gala featured a breathtaking performance\nthat seamlessly blended traditional Chinese martial arts with\ncutting-edge technology: a carefully designed martial arts routine\nperformed by humanoid robots. This was not merely entertainment for the\naudience; it was a powerful declaration of China’s rapid and impressive\nadvancements in the fields of robotics and artificial intelligence.\nCompared to their debut just a year earlier, the 2026 robots\ndemonstrated astonishing progress in every aspect. Gone were the stiff,\nawkward and hesitant movements of the past. Dozens of Unitree’s G1\nhumanoid robots perfectly carried out complex and skillful actions,\nincluding high-speed flips, synchronized (同步的) nunchaku swings, and\neven the delicate, unsteady steps of “Drunken Fist.” They maintained\nstable balance, performed flawless formations, and interacted safely\nwith young human martial artists, a breakthrough that reflected huge\nleaps in both stability and dynamic motion control.\nBehind the striking performance lies a *convergence* of advanced\ntechnologies that together make such precise movements possible. Powered\nby highly developed AI control systems and equipped with LiDAR\n(激光雷达) sensors, the robots can map the 3D stage environment in real\ntime, enabling them to recognize their positions accurately and adjust\ntheir movements instantly to stay perfectly synchronized. Their flexible\njumps and flips rely on powerful actuators (执行器) and massive\nprofessional training data, proving that machines can now attain a level\nof athleticism once considered unique to humans.\nThe meaning of the display goes far beyond artistic effect. As a\nmilestone in intelligent manufacturing, the show underlines China’s\ngrowing competitiveness in the global humanoid robot industry. While\nChinese companies take a major share of the world market, the gala\nperformance more importantly shows the nation’s strong ability to\ncombine AI technology with a complete supply chain. It suggests a future\nwhere robots, having mastered the precision of kung fu, will undertake\ncomplex tasks in industry and daily life, turning technological strength\ninto practical social value.\n\n【题目】\nThe underlined word “convergence” in Paragraph 3 most probably means _________.","options":[{"key":"A","text":"combination"},{"key":"B","text":"competition"},{"key":"C","text":"conflict"},{"key":"D","text":"creativity"}],"answer":"A","explanation":"convergence意为融合、结合，指传统武术与现代科技结合，故选A。","chapter":"阅读"},{"id":"english-read-8","origNo":8,"type":"single","stem":"【阅读材料】\nThe 2026 CCTV Spring Festival Gala featured a breathtaking performance\nthat seamlessly blended traditional Chinese martial arts with\ncutting-edge technology: a carefully designed martial arts routine\nperformed by humanoid robots. This was not merely entertainment for the\naudience; it was a powerful declaration of China’s rapid and impressive\nadvancements in the fields of robotics and artificial intelligence.\nCompared to their debut just a year earlier, the 2026 robots\ndemonstrated astonishing progress in every aspect. Gone were the stiff,\nawkward and hesitant movements of the past. Dozens of Unitree’s G1\nhumanoid robots perfectly carried out complex and skillful actions,\nincluding high-speed flips, synchronized (同步的) nunchaku swings, and\neven the delicate, unsteady steps of “Drunken Fist.” They maintained\nstable balance, performed flawless formations, and interacted safely\nwith young human martial artists, a breakthrough that reflected huge\nleaps in both stability and dynamic motion control.\nBehind the striking performance lies a *convergence* of advanced\ntechnologies that together make such precise movements possible. Powered\nby highly developed AI control systems and equipped with LiDAR\n(激光雷达) sensors, the robots can map the 3D stage environment in real\ntime, enabling them to recognize their positions accurately and adjust\ntheir movements instantly to stay perfectly synchronized. Their flexible\njumps and flips rely on powerful actuators (执行器) and massive\nprofessional training data, proving that machines can now attain a level\nof athleticism once considered unique to humans.\nThe meaning of the display goes far beyond artistic effect. As a\nmilestone in intelligent manufacturing, the show underlines China’s\ngrowing competitiveness in the global humanoid robot industry. While\nChinese companies take a major share of the world market, the gala\nperformance more importantly shows the nation’s strong ability to\ncombine AI technology with a complete supply chain. It suggests a future\nwhere robots, having mastered the precision of kung fu, will undertake\ncomplex tasks in industry and daily life, turning technological strength\ninto practical social value.\n\n【题目】\nHow did the robots maintain perfect synchronization during the performance?","options":[{"key":"A","text":"They followed fixed routes without any adjustment."},{"key":"B","text":"They were remotely controlled by engineers behind the stage."},{"key":"C","text":"They used sensors to map the stage and adjust movements in real time."},{"key":"D","text":"They responded to voice commands from human performers."}],"answer":"C","explanation":"机器人靠传感器实时映射舞台并调整动作以保持同步，故选C。","chapter":"阅读"},{"id":"english-read-9","origNo":9,"type":"single","stem":"【阅读材料】\nThe 2026 CCTV Spring Festival Gala featured a breathtaking performance\nthat seamlessly blended traditional Chinese martial arts with\ncutting-edge technology: a carefully designed martial arts routine\nperformed by humanoid robots. This was not merely entertainment for the\naudience; it was a powerful declaration of China’s rapid and impressive\nadvancements in the fields of robotics and artificial intelligence.\nCompared to their debut just a year earlier, the 2026 robots\ndemonstrated astonishing progress in every aspect. Gone were the stiff,\nawkward and hesitant movements of the past. Dozens of Unitree’s G1\nhumanoid robots perfectly carried out complex and skillful actions,\nincluding high-speed flips, synchronized (同步的) nunchaku swings, and\neven the delicate, unsteady steps of “Drunken Fist.” They maintained\nstable balance, performed flawless formations, and interacted safely\nwith young human martial artists, a breakthrough that reflected huge\nleaps in both stability and dynamic motion control.\nBehind the striking performance lies a *convergence* of advanced\ntechnologies that together make such precise movements possible. Powered\nby highly developed AI control systems and equipped with LiDAR\n(激光雷达) sensors, the robots can map the 3D stage environment in real\ntime, enabling them to recognize their positions accurately and adjust\ntheir movements instantly to stay perfectly synchronized. Their flexible\njumps and flips rely on powerful actuators (执行器) and massive\nprofessional training data, proving that machines can now attain a level\nof athleticism once considered unique to humans.\nThe meaning of the display goes far beyond artistic effect. As a\nmilestone in intelligent manufacturing, the show underlines China’s\ngrowing competitiveness in the global humanoid robot industry. While\nChinese companies take a major share of the world market, the gala\nperformance more importantly shows the nation’s strong ability to\ncombine AI technology with a complete supply chain. It suggests a future\nwhere robots, having mastered the precision of kung fu, will undertake\ncomplex tasks in industry and daily life, turning technological strength\ninto practical social value.\n\n【题目】\nWhat can be inferred from the last paragraph?","options":[{"key":"A","text":"The performance was meant to show robots are better than humans at martial arts."},{"key":"B","text":"China has led the world in all fields of intelligent manufacturing."},{"key":"C","text":"Human performers will gradually disappear from traditional cultural galas."},{"key":"D","text":"The performance stood for China’s progress in AI and manufacturing integration."}],"answer":"D","explanation":"末段暗示该表演代表中国在AI与制造业融合上的进步，故选D。","chapter":"阅读"},{"id":"english-read-10","origNo":10,"type":"single","stem":"【阅读材料】\nThe 2026 CCTV Spring Festival Gala featured a breathtaking performance\nthat seamlessly blended traditional Chinese martial arts with\ncutting-edge technology: a carefully designed martial arts routine\nperformed by humanoid robots. This was not merely entertainment for the\naudience; it was a powerful declaration of China’s rapid and impressive\nadvancements in the fields of robotics and artificial intelligence.\nCompared to their debut just a year earlier, the 2026 robots\ndemonstrated astonishing progress in every aspect. Gone were the stiff,\nawkward and hesitant movements of the past. Dozens of Unitree’s G1\nhumanoid robots perfectly carried out complex and skillful actions,\nincluding high-speed flips, synchronized (同步的) nunchaku swings, and\neven the delicate, unsteady steps of “Drunken Fist.” They maintained\nstable balance, performed flawless formations, and interacted safely\nwith young human martial artists, a breakthrough that reflected huge\nleaps in both stability and dynamic motion control.\nBehind the striking performance lies a *convergence* of advanced\ntechnologies that together make such precise movements possible. Powered\nby highly developed AI control systems and equipped with LiDAR\n(激光雷达) sensors, the robots can map the 3D stage environment in real\ntime, enabling them to recognize their positions accurately and adjust\ntheir movements instantly to stay perfectly synchronized. Their flexible\njumps and flips rely on powerful actuators (执行器) and massive\nprofessional training data, proving that machines can now attain a level\nof athleticism once considered unique to humans.\nThe meaning of the display goes far beyond artistic effect. As a\nmilestone in intelligent manufacturing, the show underlines China’s\ngrowing competitiveness in the global humanoid robot industry. While\nChinese companies take a major share of the world market, the gala\nperformance more importantly shows the nation’s strong ability to\ncombine AI technology with a complete supply chain. It suggests a future\nwhere robots, having mastered the precision of kung fu, will undertake\ncomplex tasks in industry and daily life, turning technological strength\ninto practical social value.\n\n【题目】\nAccording to the passage, what future role are these robots expected to play?","options":[{"key":"A","text":"Replacing all human workers in factories."},{"key":"B","text":"Performing only in entertainment shows."},{"key":"C","text":"Taking on complex tasks in industry and daily life."},{"key":"D","text":"Competing in international martial arts competitions."}],"answer":"C","explanation":"机器人未来将在工业和日常生活中承担复杂任务，故选C。","chapter":"阅读"},{"id":"english-read-11","origNo":11,"type":"single","stem":"【阅读材料】\nPersonal growth is often mistakenly regarded as a smooth upward path of\nachievements. Yet psychological research and real-life experiences\nconfirm a different truth: resilience — the ability to adapt and develop\namid difficulties  — is the unseen force driving deep and lasting\ngrowth. In an era of rapid changes and unexpected challenges, developing\nresilience is not just a survival skill but a key part of self-\ndevelopment, turning setbacks into stepping stones.\nThe link between difficulties and growth lies in the positive\npsychological changes after tough life events. Studies show that those\nwho deal with hardships rather than avoid them gain greater self-\nawareness, deeper understanding of others, and a stronger sense of\npurpose. For example, people who survive health problems with resilience\noften adjust their thinking, regaining confidence in their own abilities\nand valuing life more. This growth does not come automatically; it comes\nfrom facing difficulties on purpose, strengthening mental strength just\nas exercise builds muscle.\nResilience also plays an important role in life changes. Young people\nentering the workplace face setbacks such as rejected plans or\ndisagreements that cause self-doubt, but resilient people see these as\nlearning chances. They analyze their mistakes, ask for advice, and\ndevelop skills to make progress. Similarly, people traveling alone\nimprove resilience by dealing with unfamiliar environments on their own,\ntrusting their decisions and adapting to difficulties. Some people argue\nthat focusing on resilience puts pressure on people to ignore pain, but\nresilience means recognizing suffering without being controlled by it.\nIt is a skill that can be developed, not an inborn quality. Simple\nmethods such as changing negative thoughts, building support groups, and\npracticing thanksgiving can strengthen it over time.\nIn a society that values quick solutions, we must realize that true\ngrowth is built on resilience. Difficulties are an essential part of\ngrowth, not a detour. Developing resilience helps us face challenges\nbravely, adapt smoothly, and become stronger. It remains the most\nreliable companion on the path to meaningful personal growth.\n\n【题目】\nWhat is the common misunderstanding about personal growth according to the passage?","options":[{"key":"A","text":"It requires great efforts to achieve."},{"key":"B","text":"It is a smooth process full of achievements."},{"key":"C","text":"It has a close connection with difficulties."},{"key":"D","text":"It can only be gained through work experience."}],"answer":"B","explanation":"常见误解是个人成长是顺利的、充满成就的过程，故选B。","chapter":"阅读"},{"id":"english-read-12","origNo":12,"type":"single","stem":"【阅读材料】\nPersonal growth is often mistakenly regarded as a smooth upward path of\nachievements. Yet psychological research and real-life experiences\nconfirm a different truth: resilience — the ability to adapt and develop\namid difficulties  — is the unseen force driving deep and lasting\ngrowth. In an era of rapid changes and unexpected challenges, developing\nresilience is not just a survival skill but a key part of self-\ndevelopment, turning setbacks into stepping stones.\nThe link between difficulties and growth lies in the positive\npsychological changes after tough life events. Studies show that those\nwho deal with hardships rather than avoid them gain greater self-\nawareness, deeper understanding of others, and a stronger sense of\npurpose. For example, people who survive health problems with resilience\noften adjust their thinking, regaining confidence in their own abilities\nand valuing life more. This growth does not come automatically; it comes\nfrom facing difficulties on purpose, strengthening mental strength just\nas exercise builds muscle.\nResilience also plays an important role in life changes. Young people\nentering the workplace face setbacks such as rejected plans or\ndisagreements that cause self-doubt, but resilient people see these as\nlearning chances. They analyze their mistakes, ask for advice, and\ndevelop skills to make progress. Similarly, people traveling alone\nimprove resilience by dealing with unfamiliar environments on their own,\ntrusting their decisions and adapting to difficulties. Some people argue\nthat focusing on resilience puts pressure on people to ignore pain, but\nresilience means recognizing suffering without being controlled by it.\nIt is a skill that can be developed, not an inborn quality. Simple\nmethods such as changing negative thoughts, building support groups, and\npracticing thanksgiving can strengthen it over time.\nIn a society that values quick solutions, we must realize that true\ngrowth is built on resilience. Difficulties are an essential part of\ngrowth, not a detour. Developing resilience helps us face challenges\nbravely, adapt smoothly, and become stronger. It remains the most\nreliable companion on the path to meaningful personal growth.\n\n【题目】\nWhich of the following is NOT a benefit of dealing with hardships actively?","options":[{"key":"A","text":"Gaining a better understanding of oneself."},{"key":"B","text":"Developing a stronger sense of purpose."},{"key":"C","text":"Avoiding all the pain in life."},{"key":"D","text":"Learning to value life more."}],"answer":"C","explanation":"应对困难不能避免所有痛苦，Avoiding all the pain并非益处，故选C。","chapter":"阅读"},{"id":"english-read-13","origNo":13,"type":"single","stem":"【阅读材料】\nPersonal growth is often mistakenly regarded as a smooth upward path of\nachievements. Yet psychological research and real-life experiences\nconfirm a different truth: resilience — the ability to adapt and develop\namid difficulties  — is the unseen force driving deep and lasting\ngrowth. In an era of rapid changes and unexpected challenges, developing\nresilience is not just a survival skill but a key part of self-\ndevelopment, turning setbacks into stepping stones.\nThe link between difficulties and growth lies in the positive\npsychological changes after tough life events. Studies show that those\nwho deal with hardships rather than avoid them gain greater self-\nawareness, deeper understanding of others, and a stronger sense of\npurpose. For example, people who survive health problems with resilience\noften adjust their thinking, regaining confidence in their own abilities\nand valuing life more. This growth does not come automatically; it comes\nfrom facing difficulties on purpose, strengthening mental strength just\nas exercise builds muscle.\nResilience also plays an important role in life changes. Young people\nentering the workplace face setbacks such as rejected plans or\ndisagreements that cause self-doubt, but resilient people see these as\nlearning chances. They analyze their mistakes, ask for advice, and\ndevelop skills to make progress. Similarly, people traveling alone\nimprove resilience by dealing with unfamiliar environments on their own,\ntrusting their decisions and adapting to difficulties. Some people argue\nthat focusing on resilience puts pressure on people to ignore pain, but\nresilience means recognizing suffering without being controlled by it.\nIt is a skill that can be developed, not an inborn quality. Simple\nmethods such as changing negative thoughts, building support groups, and\npracticing thanksgiving can strengthen it over time.\nIn a society that values quick solutions, we must realize that true\ngrowth is built on resilience. Difficulties are an essential part of\ngrowth, not a detour. Developing resilience helps us face challenges\nbravely, adapt smoothly, and become stronger. It remains the most\nreliable companion on the path to meaningful personal growth.\n\n【题目】\nWhat can we infer from the passage about resilience?","options":[{"key":"A","text":"It can be improved through certain methods."},{"key":"B","text":"It is a skill that only a few people can have."},{"key":"C","text":"It has nothing to do with life changes."},{"key":"D","text":"It makes people ignore their sufferings."}],"answer":"A","explanation":"韧性可通过某些方法培养提升，并非少数人专属，故选A。","chapter":"阅读"},{"id":"english-read-14","origNo":14,"type":"single","stem":"【阅读材料】\nPersonal growth is often mistakenly regarded as a smooth upward path of\nachievements. Yet psychological research and real-life experiences\nconfirm a different truth: resilience — the ability to adapt and develop\namid difficulties  — is the unseen force driving deep and lasting\ngrowth. In an era of rapid changes and unexpected challenges, developing\nresilience is not just a survival skill but a key part of self-\ndevelopment, turning setbacks into stepping stones.\nThe link between difficulties and growth lies in the positive\npsychological changes after tough life events. Studies show that those\nwho deal with hardships rather than avoid them gain greater self-\nawareness, deeper understanding of others, and a stronger sense of\npurpose. For example, people who survive health problems with resilience\noften adjust their thinking, regaining confidence in their own abilities\nand valuing life more. This growth does not come automatically; it comes\nfrom facing difficulties on purpose, strengthening mental strength just\nas exercise builds muscle.\nResilience also plays an important role in life changes. Young people\nentering the workplace face setbacks such as rejected plans or\ndisagreements that cause self-doubt, but resilient people see these as\nlearning chances. They analyze their mistakes, ask for advice, and\ndevelop skills to make progress. Similarly, people traveling alone\nimprove resilience by dealing with unfamiliar environments on their own,\ntrusting their decisions and adapting to difficulties. Some people argue\nthat focusing on resilience puts pressure on people to ignore pain, but\nresilience means recognizing suffering without being controlled by it.\nIt is a skill that can be developed, not an inborn quality. Simple\nmethods such as changing negative thoughts, building support groups, and\npracticing thanksgiving can strengthen it over time.\nIn a society that values quick solutions, we must realize that true\ngrowth is built on resilience. Difficulties are an essential part of\ngrowth, not a detour. Developing resilience helps us face challenges\nbravely, adapt smoothly, and become stronger. It remains the most\nreliable companion on the path to meaningful personal growth.\n\n【题目】\nWhat does the author think of difficulties in personal growth?","options":[{"key":"A","text":"They are unnecessary obstacles to avoid."},{"key":"B","text":"They are key parts of true personal growth."},{"key":"C","text":"They make people lose confidence easily."},{"key":"D","text":"They can only be solved with quick solutions."}],"answer":"B","explanation":"作者认为困难是真正个人成长的关键组成部分，故选B。","chapter":"阅读"},{"id":"english-read-15","origNo":15,"type":"single","stem":"【阅读材料】\nPersonal growth is often mistakenly regarded as a smooth upward path of\nachievements. Yet psychological research and real-life experiences\nconfirm a different truth: resilience — the ability to adapt and develop\namid difficulties  — is the unseen force driving deep and lasting\ngrowth. In an era of rapid changes and unexpected challenges, developing\nresilience is not just a survival skill but a key part of self-\ndevelopment, turning setbacks into stepping stones.\nThe link between difficulties and growth lies in the positive\npsychological changes after tough life events. Studies show that those\nwho deal with hardships rather than avoid them gain greater self-\nawareness, deeper understanding of others, and a stronger sense of\npurpose. For example, people who survive health problems with resilience\noften adjust their thinking, regaining confidence in their own abilities\nand valuing life more. This growth does not come automatically; it comes\nfrom facing difficulties on purpose, strengthening mental strength just\nas exercise builds muscle.\nResilience also plays an important role in life changes. Young people\nentering the workplace face setbacks such as rejected plans or\ndisagreements that cause self-doubt, but resilient people see these as\nlearning chances. They analyze their mistakes, ask for advice, and\ndevelop skills to make progress. Similarly, people traveling alone\nimprove resilience by dealing with unfamiliar environments on their own,\ntrusting their decisions and adapting to difficulties. Some people argue\nthat focusing on resilience puts pressure on people to ignore pain, but\nresilience means recognizing suffering without being controlled by it.\nIt is a skill that can be developed, not an inborn quality. Simple\nmethods such as changing negative thoughts, building support groups, and\npracticing thanksgiving can strengthen it over time.\nIn a society that values quick solutions, we must realize that true\ngrowth is built on resilience. Difficulties are an essential part of\ngrowth, not a detour. Developing resilience helps us face challenges\nbravely, adapt smoothly, and become stronger. It remains the most\nreliable companion on the path to meaningful personal growth.\n\n【题目】\nWhat is the main idea of the passage?","options":[{"key":"A","text":"The ways to deal with life’s difficulties."},{"key":"B","text":"The importance of quick solutions in modern society."},{"key":"C","text":"Resilience is the key driver of personal growth."},{"key":"D","text":"Different opinions on the role of resilience."}],"answer":"C","explanation":"文章主旨论述韧性是个人成长的关键驱动力，故选C。","chapter":"阅读"},{"id":"english-read-16","origNo":16,"type":"single","stem":"【阅读材料】\nWaking up just one hour earlier could reduce a person’s risk of major\ndepression by 23%, suggests a sweeping new genetic study. Previous\nobservational studies have shown that night owls are twice as likely to\nsuffer from depression as early risers, regardless of how long they\nsleep. In 2018, senior author Celine Vetter, assistant professor of\nintegrative physiology at CU Boulder, published a long-term study of\n32,000 nurses showing that “early risers” were up to 27% less likely to\ndevelop depression over the course of four years.\nTo get a clearer sense of whether shifting sleep time earlier is truly\nprotective, and how much shift is required, lead author Lyas Daglas, M.\nD．, turned to data from the DNA testing company and ten used a method\ncalled “*Mendelian randomization*” to decipher (破译) cause and effect.\nMore than 340 common genetic variants, including variants in the\nso-called “clock gene” PER2, are known to influence a person’s internal\nclock, and genes collectively explain 12-42% of our sleep time\npreference. The researchers assessed deidentified genetic data on these\nvariants from up to 850,000 individuals, including data from 85,000 who\nhad worn wearable sleep trackers for 7 days and 250,000 who had filled\nout sleep-preference questionnaires. In the largest of these samples,\nabout a third of surveyed people self-identified as early risers, 9%\nwere night owls and the rest were in the middle.\nWith this information in hand, the researchers turned to a different\nsample which included genetic information along with anonymized (匿名的)\nmedical and prescription records and surveys about diagnosis of major\ndepressive disorder. Using new statistical techniques, they asked: do\nthose with genetic variants which *predispose them to be early risers*\nalso have a lower risk of depression? The answer is a firm yes.\nEach-one-hour earlier sleep midpoint (halfway between bedtime and wake\ntime) corresponded with a 23% lower risk of major depressive disorder.\nThis suggests that if someone who normally goes to bed at 1 a.m. goes to\nbed at midnight instead and sleeps the same duration, they could cut\ntheir risk by 23%; if they go to bed at 11 p.m. they could cut it by\nabout 40%.\n\n【题目】\nWhat does the first paragraph mainly talk about?","options":[{"key":"A","text":"The significant role of gene action in depression."},{"key":"B","text":"A new observational study about causes of depression."},{"key":"C","text":"The close relationship between depression and sleep time."},{"key":"D","text":"Whether early risers are less likely to suffer from depression."}],"answer":"C","explanation":"第一段主要讲抑郁与睡眠时间的密切关系，故选C。","chapter":"阅读"},{"id":"english-read-17","origNo":17,"type":"single","stem":"【阅读材料】\nWaking up just one hour earlier could reduce a person’s risk of major\ndepression by 23%, suggests a sweeping new genetic study. Previous\nobservational studies have shown that night owls are twice as likely to\nsuffer from depression as early risers, regardless of how long they\nsleep. In 2018, senior author Celine Vetter, assistant professor of\nintegrative physiology at CU Boulder, published a long-term study of\n32,000 nurses showing that “early risers” were up to 27% less likely to\ndevelop depression over the course of four years.\nTo get a clearer sense of whether shifting sleep time earlier is truly\nprotective, and how much shift is required, lead author Lyas Daglas, M.\nD．, turned to data from the DNA testing company and ten used a method\ncalled “*Mendelian randomization*” to decipher (破译) cause and effect.\nMore than 340 common genetic variants, including variants in the\nso-called “clock gene” PER2, are known to influence a person’s internal\nclock, and genes collectively explain 12-42% of our sleep time\npreference. The researchers assessed deidentified genetic data on these\nvariants from up to 850,000 individuals, including data from 85,000 who\nhad worn wearable sleep trackers for 7 days and 250,000 who had filled\nout sleep-preference questionnaires. In the largest of these samples,\nabout a third of surveyed people self-identified as early risers, 9%\nwere night owls and the rest were in the middle.\nWith this information in hand, the researchers turned to a different\nsample which included genetic information along with anonymized (匿名的)\nmedical and prescription records and surveys about diagnosis of major\ndepressive disorder. Using new statistical techniques, they asked: do\nthose with genetic variants which *predispose them to be early risers*\nalso have a lower risk of depression? The answer is a firm yes.\nEach-one-hour earlier sleep midpoint (halfway between bedtime and wake\ntime) corresponded with a 23% lower risk of major depressive disorder.\nThis suggests that if someone who normally goes to bed at 1 a.m. goes to\nbed at midnight instead and sleeps the same duration, they could cut\ntheir risk by 23%; if they go to bed at 11 p.m. they could cut it by\nabout 40%.\n\n【题目】\nHow did Lyas Daghlas decipher cause and effect?","options":[{"key":"A","text":"By exploring the influence of genes on depression."},{"key":"B","text":"By analyzing samples of surveyed people’s self-identification."},{"key":"C","text":"By tracking individuals diagnosed with depressive disorder."},{"key":"D","text":"By proving the decisive role sleep time plays in genetic variants."}],"answer":"A","explanation":"Lyas Daghlas通过探究基因对抑郁的影响来厘清因果关系，故选A。","chapter":"阅读"},{"id":"english-read-18","origNo":18,"type":"single","stem":"【阅读材料】\nWaking up just one hour earlier could reduce a person’s risk of major\ndepression by 23%, suggests a sweeping new genetic study. Previous\nobservational studies have shown that night owls are twice as likely to\nsuffer from depression as early risers, regardless of how long they\nsleep. In 2018, senior author Celine Vetter, assistant professor of\nintegrative physiology at CU Boulder, published a long-term study of\n32,000 nurses showing that “early risers” were up to 27% less likely to\ndevelop depression over the course of four years.\nTo get a clearer sense of whether shifting sleep time earlier is truly\nprotective, and how much shift is required, lead author Lyas Daglas, M.\nD．, turned to data from the DNA testing company and ten used a method\ncalled “*Mendelian randomization*” to decipher (破译) cause and effect.\nMore than 340 common genetic variants, including variants in the\nso-called “clock gene” PER2, are known to influence a person’s internal\nclock, and genes collectively explain 12-42% of our sleep time\npreference. The researchers assessed deidentified genetic data on these\nvariants from up to 850,000 individuals, including data from 85,000 who\nhad worn wearable sleep trackers for 7 days and 250,000 who had filled\nout sleep-preference questionnaires. In the largest of these samples,\nabout a third of surveyed people self-identified as early risers, 9%\nwere night owls and the rest were in the middle.\nWith this information in hand, the researchers turned to a different\nsample which included genetic information along with anonymized (匿名的)\nmedical and prescription records and surveys about diagnosis of major\ndepressive disorder. Using new statistical techniques, they asked: do\nthose with genetic variants which *predispose them to be early risers*\nalso have a lower risk of depression? The answer is a firm yes.\nEach-one-hour earlier sleep midpoint (halfway between bedtime and wake\ntime) corresponded with a 23% lower risk of major depressive disorder.\nThis suggests that if someone who normally goes to bed at 1 a.m. goes to\nbed at midnight instead and sleeps the same duration, they could cut\ntheir risk by 23%; if they go to bed at 11 p.m. they could cut it by\nabout 40%.\n\n【题目】\nWhat is Lyas Daghals’s research mainly based on?","options":[{"key":"A","text":"Medical treatment records of early risers."},{"key":"B","text":"The genetic research and data about DNA"},{"key":"C","text":"A comprehensive analysis of different samples."},{"key":"D","text":"250,000 people’s self-identification and questionnaires."}],"answer":"C","explanation":"研究基于基因研究和DNA数据分析，故选B。","chapter":"阅读"},{"id":"english-read-19","origNo":19,"type":"single","stem":"【阅读材料】\nWaking up just one hour earlier could reduce a person’s risk of major\ndepression by 23%, suggests a sweeping new genetic study. Previous\nobservational studies have shown that night owls are twice as likely to\nsuffer from depression as early risers, regardless of how long they\nsleep. In 2018, senior author Celine Vetter, assistant professor of\nintegrative physiology at CU Boulder, published a long-term study of\n32,000 nurses showing that “early risers” were up to 27% less likely to\ndevelop depression over the course of four years.\nTo get a clearer sense of whether shifting sleep time earlier is truly\nprotective, and how much shift is required, lead author Lyas Daglas, M.\nD．, turned to data from the DNA testing company and ten used a method\ncalled “*Mendelian randomization*” to decipher (破译) cause and effect.\nMore than 340 common genetic variants, including variants in the\nso-called “clock gene” PER2, are known to influence a person’s internal\nclock, and genes collectively explain 12-42% of our sleep time\npreference. The researchers assessed deidentified genetic data on these\nvariants from up to 850,000 individuals, including data from 85,000 who\nhad worn wearable sleep trackers for 7 days and 250,000 who had filled\nout sleep-preference questionnaires. In the largest of these samples,\nabout a third of surveyed people self-identified as early risers, 9%\nwere night owls and the rest were in the middle.\nWith this information in hand, the researchers turned to a different\nsample which included genetic information along with anonymized (匿名的)\nmedical and prescription records and surveys about diagnosis of major\ndepressive disorder. Using new statistical techniques, they asked: do\nthose with genetic variants which *predispose them to be early risers*\nalso have a lower risk of depression? The answer is a firm yes.\nEach-one-hour earlier sleep midpoint (halfway between bedtime and wake\ntime) corresponded with a 23% lower risk of major depressive disorder.\nThis suggests that if someone who normally goes to bed at 1 a.m. goes to\nbed at midnight instead and sleeps the same duration, they could cut\ntheir risk by 23%; if they go to bed at 11 p.m. they could cut it by\nabout 40%.\n\n【题目】\nHow do you understand the underlined part in the last paragraph?","options":[{"key":"A","text":"Make them more likely to rise early."},{"key":"B","text":"Change early risers’ habits."},{"key":"C","text":"Force them to change their chronotype"},{"key":"D","text":"Lead them to shift sleep time"}],"answer":"A","explanation":"该部分意为使他们更倾向于早起，故选A。","chapter":"阅读"},{"id":"english-read-20","origNo":20,"type":"single","stem":"【阅读材料】\nWaking up just one hour earlier could reduce a person’s risk of major\ndepression by 23%, suggests a sweeping new genetic study. Previous\nobservational studies have shown that night owls are twice as likely to\nsuffer from depression as early risers, regardless of how long they\nsleep. In 2018, senior author Celine Vetter, assistant professor of\nintegrative physiology at CU Boulder, published a long-term study of\n32,000 nurses showing that “early risers” were up to 27% less likely to\ndevelop depression over the course of four years.\nTo get a clearer sense of whether shifting sleep time earlier is truly\nprotective, and how much shift is required, lead author Lyas Daglas, M.\nD．, turned to data from the DNA testing company and ten used a method\ncalled “*Mendelian randomization*” to decipher (破译) cause and effect.\nMore than 340 common genetic variants, including variants in the\nso-called “clock gene” PER2, are known to influence a person’s internal\nclock, and genes collectively explain 12-42% of our sleep time\npreference. The researchers assessed deidentified genetic data on these\nvariants from up to 850,000 individuals, including data from 85,000 who\nhad worn wearable sleep trackers for 7 days and 250,000 who had filled\nout sleep-preference questionnaires. In the largest of these samples,\nabout a third of surveyed people self-identified as early risers, 9%\nwere night owls and the rest were in the middle.\nWith this information in hand, the researchers turned to a different\nsample which included genetic information along with anonymized (匿名的)\nmedical and prescription records and surveys about diagnosis of major\ndepressive disorder. Using new statistical techniques, they asked: do\nthose with genetic variants which *predispose them to be early risers*\nalso have a lower risk of depression? The answer is a firm yes.\nEach-one-hour earlier sleep midpoint (halfway between bedtime and wake\ntime) corresponded with a 23% lower risk of major depressive disorder.\nThis suggests that if someone who normally goes to bed at 1 a.m. goes to\nbed at midnight instead and sleeps the same duration, they could cut\ntheir risk by 23%; if they go to bed at 11 p.m. they could cut it by\nabout 40%.\n\n【题目】\nWhich can be the suitable title for this text?","options":[{"key":"A","text":"Risk of Depression Decreases When Sleeping Time Increases"},{"key":"B","text":"Genes Have More Impact on Depression than Sleep Time Does"},{"key":"C","text":"A New Research Suggests Early Risers Carry Clock Gene called PER2"},{"key":"D","text":"Moving Sleep Time An Hour Earlier Could Cut Depression Risk by 23%"}],"answer":"D","explanation":"标题应概括将睡眠时间提前一小时可降低23%抑郁风险，故选D。","chapter":"阅读"}]};
